11	    10	/**
12	    11	 * DNS lookup — resolves A / AAAA / MX / TXT / NS / CNAME / SOA for a domain via
13	    12	 * node:dns. Public DNS only (no connections are made to the target), but we still
14	    13	 * validate the hostname and cap output. Rate-limited per IP.
15	    14	 */
16	    15	
17	    16	const TIMEOUT_MS = 5000;
18	    17	const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
19	    18	type RecordType = (typeof TYPES)[number];
20	    19	
21	    20	function withTimeout<T>(p: Promise<T>): Promise<T> {
22	    21	  return Promise.race([
23	    22	    p,
24	    23	    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timeout")), TIMEOUT_MS)),
25	    24	  ]);
26	    25	}
27	    26	
28	    27	export async function POST(req: Request) {
29	    28	  const limited = toolRateLimitByIp(req, "dns", { max: 30, windowMs: 60_000 });
30	    29	  if (limited) return limited;
31	    30	
32	    31	  const raw = await readField(req, "domain");
33	    32	  const host = extractHost(raw);
34	    33	  if (!host || !isPlausibleHost(host)) return jsonError("Enter a valid domain name.");
35	    34	  if (host === "localhost") return jsonError("That host is not allowed.");
36	    35	
37	    36	  const resolver = new Resolver({ timeout: TIMEOUT_MS, tries: 2 });
38	    37	
39	    38	  async function resolveType(type: RecordType): Promise<string[]> {
40	    39	    try {
41	    40	      switch (type) {
42	    41	        case "A":
43	    42	          // Drop private/reserved answers so this public tool can't be used to
44	    43	          // enumerate internal names the resolver happens to know (RFC1918,
45	    44	          // 127/8, 169.254/16, etc.).
46	    45	          return (await withTimeout(resolver.resolve4(host!))).filter((ip) => !isBlockedIp(ip));
47	    46	        case "AAAA":
48	    47	          return (await withTimeout(resolver.resolve6(host!))).filter((ip) => !isBlockedIp(ip));
49	    48	        case "MX": {
50	    49	          const mx = await withTimeout(resolver.resolveMx(host!));
51	    50	          return mx
52	    51	            .sort((a, b) => a.priority - b.priority)
53	    52	            .map((r) => `${r.priority}\t${r.exchange}`);
54	    53	        }
55	    54	        case "TXT": {
56	    55	          const txt = await withTimeout(resolver.resolveTxt(host!));
57	    56	          return txt.map((chunks) => chunks.join(""));
58	    57	        }
59	    58	        case "NS":
60	    59	          return await withTimeout(resolver.resolveNs(host!));
61	    60	        case "CNAME":
62	    61	          return await withTimeout(resolver.resolveCname(host!));
63	    62	        case "SOA": {
64	    63	          const soa = await withTimeout(resolver.resolveSoa(host!));
65	    64	          return [
66	    65	            `${soa.nsname} ${soa.hostmaster} serial=${soa.serial} refresh=${soa.refresh} retry=${soa.retry} expire=${soa.expire} minttl=${soa.minttl}`,
67	    66	          ];
68	    67	        }
69	    68	      }
70	    69	    } catch {
71	    70	      return [];
72	    71	    }
73	    72	  }
74	    73	
75	    74	  try {
76	    75	    const settled = await Promise.all(
77	    76	      TYPES.map(async (t) => [t, (await resolveType(t)).slice(0, 100)] as const),
78	    77	    );
79	    78	    const records: Record<string, string[]> = {};
80	    79	    for (const [t, vals] of settled) records[t] = vals;
81	    80	    const total = Object.values(records).reduce((n, v) => n + v.length, 0);
82	    81	    if (total === 0) return jsonError("No DNS records found (the domain may not exist).", 404);
83	    82	    return NextResponse.json({ ok: true, host, records });
84	    83	  } catch {
85	    84	    return jsonError("DNS lookup failed.", 502);
86	    85	  }
87	    86	}
