172	    15	/**
173	    16	 * HTTP header inspector — fetches a URL and returns the status + response headers.
174	    17	 *
175	    18	 * SSRF guard, in layers:
176	    19	 *   1. Only http/https schemes.
177	    20	 *   2. `resolvePublicHost` resolves the host and rejects if ANY resolved address
178	    21	 *      is private / loopback / link-local / reserved.
179	    22	 *   3. The connection is PINNED to an address vetted in step 2 (see
180	    23	 *      `pinnedAgent`), so the name is never resolved a second time.
181	    24	 *   4. Redirects are NOT followed (`redirect: "manual"`) — we only report the
182	    25	 *      Location header, so we can't be bounced to an internal endpoint.
183	    26	 *   5. 5s timeout, header values capped, the body is never read.
184	    27	 *
185	    28	 * Step 3 used to be missing, and steps 2 and 4 do not cover the gap it left.
186	    29	 * `resolvePublicHost(url.hostname)` was called for its throw-or-don't side
187	    30	 * effect and its returned `addresses` were discarded; the fetch that followed
188	    31	 * was handed the HOSTNAME, so the runtime resolved it AGAIN on the way out.
189	    32	 * That is a textbook DNS-rebinding window: an attacker points a name they
190	    33	 * control at a public IP with a 0-second TTL, we check it and approve it, and
191	    34	 * by the time undici opens the socket the same name answers 127.0.0.1. The
192	    35	 * request then leaves from inside the trust boundary — Proxmox on
193	    36	 * 127.0.0.1:8006, the app itself on :3000, anything on the 10.20.0.0/24 VM
194	    37	 * bridge — and we hand the caller back its status line and every response
195	    38	 * header. `resolvePublicHost` returns `addresses` precisely so callers can
196	    39	 * close this; port-checker and ssl-checker already did, this route did not.
197	    40	 */
198	    41	
199	    42	const TIMEOUT_MS = 5000;
200	    43	
201	    44	/**
202	    45	 * An undici Agent whose DNS resolution is hard-wired to an already-vetted
203	    46	 * address. Host and SNI still come from the URL, so virtual hosts and TLS
204	    47	 * certificate validation behave normally — only the address we dial is fixed.
205	    48	 *
206	    49	 * undici's connector calls `lookup` with `{ all: true }` and expects an ARRAY of
207	    50	 * `{ address, family }`; node's plain `net.connect` contract is the positional
208	    51	 * `(err, address, family)` form. Getting this wrong does not fail the build, it
209	    52	 * fails every request at runtime with "Invalid IP address: undefined" — which is
210	    53	 * how the first cut of this fix was caught — so both shapes are answered here.
211	    54	 */
212	    55	type LookupCallback = (err: Error | null, addresses: unknown, family?: number) => void;
213	    56	
214	    57	function pinnedAgent(address: string): Agent {
215	    58	  const family = net.isIP(address);
216	    59	  return new Agent({
217	    60	    connect: {
218	    61	      lookup: (_hostname: string, options: { all?: boolean }, callback: LookupCallback) => {
219	    62	        if (options?.all) callback(null, [{ address, family }]);
220	    63	        else callback(null, address, family);
221	    64	      },
222	    65	    } as never,
223	    66	  });
224	    67	}
