303	     9	export const runtime = "nodejs";
304	    10	export const dynamic = "force-dynamic";
305	    11	
306	    12	/**
307	    13	 * Minecraft Server List Ping (Java Edition) over raw TCP.
308	    14	 *
309	    15	 * Implements the modern JSON handshake: we send a Handshake packet (next state =
310	    16	 * status) followed by a Status Request, then read the length-prefixed JSON status
311	    17	 * the server replies with — players online/max, MOTD, version, favicon presence —
