281	/** `$12.99` from integer cents. Returns null so callers can't print a fake price. */
282	export function formatPrice(cents: number | null): string | null {
283	  if (cents === null || !Number.isFinite(cents)) return null;
284	  return `$${(cents / 100).toFixed(2)}`;
285	}

  1	/**
  2	 * Shared brief → names → live availability → ranked results pipeline.
  3	 *
  4	 * BOTH surfaces of the domain-name generator run through here:
  5	 *   - the public, SEO marketing tool  (app/api/tools/domain-generator/route.ts)
  6	 *   - the signed-in customer portal    (app/api/dashboard/domains/generate/route.ts)
  7	 *
  8	 * The orchestration lived inline in the public route. A second copy for the
  9	 * portal would have been this codebase's single most common defect — two answers
 10	 * to "how do we turn a brief into available names", drifting apart. So the whole
 11	 * pipeline is one function, `generateSuggestions`, and each route contributes
 12	 * only what genuinely differs: how the caller is identified and throttled, and
 13	 * whether the visitor is signed in.
 14	 *
 15	 * Honesty invariants enforced here, not in the UI:
 16	 *   - a result is only ever "available" when the REGISTRAR returned a real price
 17	 *     for it (that guarantee comes from domain-availability.ts and is preserved
 18	 *     verbatim by `toSuggestResult`);
 19	 *   - when the registrar can't be reached the name degrades to "unknown"
 20	 *     ("couldn't verify"), never to "available";
 21	 *   - a price is only carried when the registrar gave one.
 22	 *
 23	 * The small helpers (`readTlds`, `buildDomains`, `mergeCandidates`,
 24	 * `toSuggestResult`, `rankSuggestions`, `partitionResults`) are pure and are
 25	 * unit-tested in test/domain-suggest.test.ts.
 26	 */
 27	
 28	import { aiAvailable, aiCandidates } from "./domain-ai";
 29	import { checkAvailabilityBatched, type DomainResult } from "./domain-availability";
 30	import { generateCandidates, type Candidate } from "./domain-generate";
 31	import { ALLOWED_TLDS, DEFAULT_TLDS, TONES, type Tone } from "./domain-vocab";
 32	
 33	/** Distinct name ideas per request. Caps the single Claude call's output. */
 34	export const MAX_NAMES = 12;
 35	
 36	/** Absolute ceiling on registrar lookups per request (names × TLDs). */
 37	export const MAX_LOOKUPS = 24;
 38	
 39	/** TLDs a caller may select at once. Raised from 3 so a search surfaces a broad
 40	 *  spread of extensions, not a token handful. The registrar spend stays bounded
 41	 *  by MAX_LOOKUPS (names × TLDs), which still fits a single batched call. */
 42	export const MAX_TLDS = 6;
 43	
 44	export const MAX_IDEA_LEN = 400;
 45	export const MAX_KEYWORDS_LEN = 120;
 46	
 47	/** A brief shorter than this is rejected before any AI or registrar spend. */
 48	export const MIN_IDEA_LEN = 8;
 49	
 50	const VALID_TONES = new Set(TONES.map((t) => t.value));
 51	
 52	export type SuggestStatus = "available" | "taken" | "unknown";
 53	
 54	export type SuggestResult = {
 55	  domain: string;
 56	  sld: string;
 57	  tld: string;
 58	  status: SuggestStatus;
 59	  premium: boolean;
 60	  /** Retail first-year price in integer cents, or null when the registrar gave none. */
 61	  priceCents: number | null;
 62	  /** Retail renewal price in integer cents, or null. */
 63	  renewCents: number | null;
 64	  style: string;
 65	  note: string;
 66	};
 67	
 68	export type SuggestResponse = {
 69	  /** "ai" when Claude produced the names, "heuristic" when the fallback did. */
 70	  source: "ai" | "heuristic";
 71	  /** False when the registrar isn't configured — every result is "unknown". */
 72	  registrarConfigured: boolean;
 73	  /** True when we skipped some registrar lookups to protect the shared budget. */
 74	  throttled: boolean;
 75	  checked: number;
 76	  tlds: string[];
 77	  results: SuggestResult[];
 78	};
 79	
 80	/* ---------------------------------------------------------------------------
 81	 * Input normalisation — pure
 82	 * ------------------------------------------------------------------------ */
 83	
 84	/** Collapse whitespace, trim, and hard-cap length. Non-strings become "". */
 85	export function readString(v: unknown, max: number): string {
 86	  return typeof v === "string" ? v.replace(/\s+/g, " ").trim().slice(0, max) : "";
 87	}
 88	
 89	export function readIdea(v: unknown): string {
 90	  return readString(v, MAX_IDEA_LEN);
 91	}
 92	
 93	export function readKeywords(v: unknown): string {
 94	  return readString(v, MAX_KEYWORDS_LEN);
 95	}
 96	
 97	/** Coerce arbitrary input to a known tone, defaulting to "any". */
 98	export function readTone(v: unknown): Tone {
 99	  const raw = readString(v, 20) as Tone;
100	  return VALID_TONES.has(raw) ? raw : "any";
101	}
102	
103	/**
104	 * Sanitise the requested TLD list: lower-cased, de-dotted, de-duplicated, only
105	 * ones we actually offer, capped at MAX_TLDS. Falls back to the defaults when
106	 * nothing valid survives.
107	 */
108	export function readTlds(v: unknown): string[] {
109	  if (!Array.isArray(v)) return [...DEFAULT_TLDS];
110	  const out: string[] = [];
111	  for (const raw of v) {
112	    if (typeof raw !== "string") continue;
113	    const tld = raw.toLowerCase().replace(/^\./, "").trim();
114	    if (ALLOWED_TLDS.has(tld) && !out.includes(tld)) out.push(tld);
115	    if (out.length >= MAX_TLDS) break;
116	  }
117	  return out.length ? out : [...DEFAULT_TLDS];
118	}
119	
120	/* ---------------------------------------------------------------------------
121	 * Candidate assembly — pure
122	 * ------------------------------------------------------------------------ */
123	
124	/**
125	 * Fill `primary` (the AI names) up to `max` with `fallback` (heuristic names),
126	 * de-duplicating on the bare label. Primary keeps its order and priority; the
127	 * fallback only ever tops up a short or missing AI list.
128	 */
129	export function mergeCandidates(
130	  primary: Candidate[] | null,
131	  fallback: Candidate[],
132	  max: number,
133	): Candidate[] {
134	  const merged = primary ? primary.slice(0, max) : [];
135	  if (merged.length >= max) return merged;
136	  const seen = new Set(merged.map((c) => c.sld));
137	  for (const c of fallback) {
138	    if (merged.length >= max) break;
139	    if (seen.has(c.sld)) continue;
140	    seen.add(c.sld);
141	    merged.push(c);
142	  }
143	  return merged;
144	}
145	
146	/**
147	 * Pair labels with TLDs, TLD-major, capped at MAX_LOOKUPS. TLD-major means the
148	 * caller's first-choice extension is checked for every name before we spend any
149	 * budget on the second choice.
150	 */
151	export function buildDomains(candidates: Candidate[], tlds: string[]): string[] {
152	  const domains: string[] = [];
153	  for (const tld of tlds) {
154	    for (const c of candidates) {
155	      if (domains.length >= MAX_LOOKUPS) return domains;
156	      domains.push(`${c.sld}.${tld}`);
157	    }
158	  }
159	  return domains;
160	}
161	
162	/* ---------------------------------------------------------------------------
163	 * Result shaping — pure
164	 * ------------------------------------------------------------------------ */
165	
166	/**
167	 * Combine a registrar availability result with its candidate's copy. The
168	 * availability status is carried through UNCHANGED — an "unknown" (couldn't
169	 * verify) is never promoted to "available" here, and a price only survives when
170	 * the registrar actually returned one.
171	 */
172	export function toSuggestResult(r: DomainResult, meta?: Pick<Candidate, "style" | "note">): SuggestResult {
173	  const dot = r.domain.lastIndexOf(".");
174	  const sld = dot >= 0 ? r.domain.slice(0, dot) : r.domain;
175	  const tld = dot >= 0 ? r.domain.slice(dot + 1) : "";
176	  return {
177	    domain: r.domain,
178	    sld,
179	    tld,
180	    status: r.status,
181	    premium: r.premium,
182	    priceCents: r.priceCents,
183	    renewCents: r.renewCents,
184	    style: meta?.style ?? "invented",
185	    note: meta?.note ?? "",
186	  };
187	}
188	
189	/** A name we can put a "Register" button on: verified free with a real price. */
190	export function isRegisterable(r: SuggestResult): boolean {
191	  return r.status === "available" && r.priceCents !== null;
192	}
193	
194	/** Available first (cheapest first within that), then unknown, then taken. Mutates + returns. */
195	export function rankSuggestions(results: SuggestResult[]): SuggestResult[] {
196	  const rank: Record<SuggestStatus, number> = { available: 0, unknown: 1, taken: 2 };
197	  results.sort(
198	    (a, b) =>
199	      rank[a.status] - rank[b.status] ||
200	      (a.priceCents ?? Number.MAX_SAFE_INTEGER) - (b.priceCents ?? Number.MAX_SAFE_INTEGER) ||
201	      a.domain.length - b.domain.length,
202	  );
203	  return results;
204	}
205	
206	/**
207	 * Split results into the three buckets both UIs render. `available` is the
208	 * differentiator: only genuinely-free, priced names. `unchecked` are the
209	 * "couldn't verify" names; `taken` are confirmed registered.
210	 */
211	export function partitionResults(results: SuggestResult[]): {
212	  available: SuggestResult[];
213	  unchecked: SuggestResult[];
214	  taken: SuggestResult[];
215	} {
216	  return {
217	    available: results.filter((r) => r.status === "available"),
218	    unchecked: results.filter((r) => r.status === "unknown"),
219	    taken: results.filter((r) => r.status === "taken"),
220	  };
221	}
222	
223	/* ---------------------------------------------------------------------------
224	 * The pipeline — the one impure step (AI + registrar)
225	 * ------------------------------------------------------------------------ */
226	
227	export type SuggestInput = {
228	  /** Already normalised + validated (>= MIN_IDEA_LEN) by the caller. */
229	  idea: string;
230	  keywords: string;
231	  tone: Tone;
232	  tlds: string[];
233	};
234	
235	/**
236	 * Names then live availability. Never throws: a missing key falls back to the
237	 * heuristic generator, a registrar failure degrades to "unknown". Returns a
238	 * response body with everything both routes need EXCEPT `signedIn`, which each
239	 * route supplies for itself.
240	 *
241	 * When the brief yields no usable labels at all, `results` is empty and the
242	 * caller should surface a "try more detail" message rather than a page of
243	 * nothing — that is the ONLY time `results` is empty (taken/unknown names still
244	 * produce results).
245	 */
246	export async function generateSuggestions(input: SuggestInput): Promise<SuggestResponse> {
247	  const { idea, keywords, tone, tlds } = input;
248	
249	  // 1) Names — Claude when the platform key is set, heuristics otherwise.
250	  let aiNames: Candidate[] | null = null;
251	  let source: "ai" | "heuristic" = "heuristic";
252	  if (aiAvailable()) {
253	    aiNames = await aiCandidates({ idea, keywords, tone, count: MAX_NAMES });
254	    if (aiNames && aiNames.length) source = "ai";
255	  }
256	  const needFallback = !aiNames || aiNames.length < MAX_NAMES;
257	  const fallback = needFallback ? generateCandidates({ idea, keywords, tone, limit: MAX_NAMES }) : [];
258	  const candidates = mergeCandidates(aiNames, fallback, MAX_NAMES);
259	
260	  const byLabel = new Map(candidates.map((c) => [c.sld, c]));
261	
262	  // 2) Availability — one batched, cached, globally-throttled registrar call.
263	  const domains = buildDomains(candidates, tlds);
264	  const availability = await checkAvailabilityBatched(domains);
265	
266	  const results = availability.results.map((r: DomainResult) => {
267	    const dot = r.domain.lastIndexOf(".");
268	    const sld = dot >= 0 ? r.domain.slice(0, dot) : r.domain;
269	    return toSuggestResult(r, byLabel.get(sld));
270	  });
271	  rankSuggestions(results);
272	
273	  return {
274	    source,
275	    registrarConfigured: availability.configured,
276	    throttled: availability.throttled,
277	    checked: results.length,
278	    tlds,
279	    results,
280	  };
281	}

